<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Apple Newsroom Clone</title>
    <style>
        :root {
            --bg-color: #f5f5f7;
            --text-primary: #1d1d1f;
            --text-secondary: #86868b;
            --accent-blue: #0071e3;
            --font-stack: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            --nav-bg: rgba(0, 0, 0, 0.8);
            --card-radius: 24px;
            --spacing-unit: 1rem;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: var(--font-stack);
            background-color: #fff; /* Top part is white */
            color: var(--text-primary);
            -webkit-font-smoothing: antialiased;
            overflow-x: hidden;
        }

        /* --- Utility Classes --- */
        .container {
            max-width: 1024px;
            margin: 0 auto;
            padding: 0 20px;
        }

        a { text-decoration: none; color: inherit; transition: opacity 0.3s; }
        a:hover { opacity: 0.6; }

        /* --- Region Banner (Top) --- */
        .region-banner {
            background-color: #333333;
            color: white;
            padding: 12px 20px;
            font-size: 13px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            position: relative;
            z-index: 100;
        }

        .region-selector {
            background-color: transparent;
            color: white;
            border: none;
            font-size: 14px;
            cursor: pointer;
            display: flex;
            align-items: center;
            gap: 10px;
            padding: 4px 12px;
            border-radius: 20px;
            background: rgba(255,255,255,0.15); /* Slight bg for visibility like screenshot */
            min-width: 200px;
            justify-content: space-between;
        }

        .btn-continue {
            background-color: white;
            color: black;
            border: none;
            padding: 6px 16px;
            border-radius: 100px;
            font-weight: 400;
            font-size: 13px;
            cursor: pointer;
        }

        .close-banner {
            background: none;
            border: none;
            color: white;
            font-size: 18px;
            cursor: pointer;
            padding-left: 10px;
        }

        /* --- Global Nav (Black) --- */
        .global-nav {
            background-color: #1d1d1f; /* Darker than banner usually, but screenshot looks dark grey/black */
            height: 44px;
            display: flex;
            align-items: center;
            justify-content: center;
            position: sticky;
            top: 0;
            z-index: 99;
            backdrop-filter: blur(20px);
        }

        .global-nav ul {
            list-style: none;
            display: flex;
            gap: 28px;
        }

        .global-nav li {
            font-size: 12px;
            color: #e8e8ed;
            cursor: pointer;
            letter-spacing: -0.01em;
        }

        .global-nav li:hover {
            color: white;
        }

        /* --- Sub Nav (Newsroom Header) --- */
        .sub-nav {
            background-color: white;
            border-bottom: 1px solid #d2d2d7;
            padding: 16px 0;
            position: sticky;
            top: 44px;
            z-index: 98;
        }

        .sub-nav-inner {
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .brand-logo {
            font-size: 22px;
            font-weight: 600;
            letter-spacing: -0.02em;
        }

        .sub-nav-links {
            display: flex;
            align-items: center;
            gap: 32px;
            font-size: 14px;
            color: var(--text-primary);
        }

        .search-box {
            background-color: #f5f5f7;
            padding: 8px 16px;
            border-radius: 980px;
            display: flex;
            align-items: center;
            gap: 8px;
            width: 180px;
            color: var(--text-secondary);
            font-size: 14px;
            cursor: text;
        }

        /* --- Main Content Area --- */
        main {
            background-color: var(--bg-color);
            padding-bottom: 80px;
            min-height: 100vh;
        }

        h1.section-title {
            font-size: 40px;
            font-weight: 700;
            margin: 60px 0 30px;
            letter-spacing: -0.003em;
        }

        /* --- Featured Grid Layout --- */
        .featured-grid {
            display: grid;
            grid-template-columns: 1.2fr 1fr; /* Image area slightly wider or equal */
            gap: 48px;
            background-color: white;
            border-radius: var(--card-radius);
            overflow: hidden;
            box-shadow: 0 4px 20px rgba(0,0,0,0.02);
            margin-bottom: 60px;
            /* To match the clean look in screenshot */
            padding-right: 40px; 
            align-items: center;
        }

        .media-container {
            display: flex;
            justify-content: center;
            align-items: center;
            padding: 40px;
            background-color: #fbfbfd;
            position: relative;
        }

        /* Simulating the phones in the image using CSS shapes/placeholders */
        .phone-mockup {
            width: 220px;
            height: 450px;
            background: #000;
            border-radius: 36px;
            border: 4px solid #333;
            position: relative;
            overflow: hidden;
            box-shadow: 0 10px 30px rgba(0,0,0,0.2);
            z-index: 2;
        }

        .phone-mockup::before { /* Notch */
            content: '';
            position: absolute;
            top: 10px;
            left: 50%;
            transform: translateX(-50%);
            width: 90px;
            height: 26px;
            background: #000;
            border-radius: 20px;
            z-index: 10;
        }

        .phone-screen {
            width: 100%;
            height: 100%;
            object-fit: cover;
            display: block;
        }

        .phone-mockup.secondary {
            transform: scale(0.95) translateY(10px);
            z-index: 1;
            margin-left: -50px; /* Overlap effect */
            border-color: #ccc;
        }

        .content-area {
            padding: 20px 0 40px 20px;
            display: flex;
            flex-direction: column;
            justify-content: center;
        }

        .tag {
            font-size: 11px;
            font-weight: 800;
            text-transform: uppercase;
            color: var(--text-secondary);
            letter-spacing: 0.02em;
            margin-bottom: 12px;
        }

        .headline {
            font-size: 38px;
            line-height: 1.1;
            font-weight: 700;
            letter-spacing: -0.03em;
            color: var(--text-primary);
            margin-bottom: 16px;
        }

        .description {
            font-size: 17px;
            line-height: 1.47;
            color: var(--text-secondary);
            font-weight: 400;
            max-width: 480px;
        }

        /* --- List Grid (Below Featured) --- */
        .news-list {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
            gap: 24px;
        }

        .news-card {
            background: white;
            border-radius: 18px;
            overflow: hidden;
            display: flex;
            flex-direction: column;
            transition: transform 0.3s ease, box-shadow 0.3s ease;
            cursor: pointer;
        }

        .news-card:hover {
            transform: scale(1.01);
            box-shadow: 0 10px 25px rgba(0,0,0,0.08);
        }

        .news-img-wrapper {
            width: 100%;
            aspect-ratio: 16/9;
            background-color: #e8e8ed;
            overflow: hidden;
            position: relative;
        }

        .news-img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.5s ease;
        }

        .news-card:hover .news-img {
            transform: scale(1.05);
        }

        .news-body {
            padding: 20px 24px 24px;
            display: flex;
            flex-direction: column;
            flex-grow: 1;
        }

        .news-tag {
            font-size: 11px;
            font-weight: 600;
            color: var(--text-secondary);
            text-transform: uppercase;
            margin-bottom: 8px;
        }

        .news-headline {
            font-size: 19px;
            line-height: 1.25;
            font-weight: 600;
            letter-spacing: -0.02em;
            color: var(--text-primary);
            margin-bottom: 8px;
        }

        .news-desc {
            font-size: 14px;
            line-height: 1.42;
            color: var(--text-secondary);
            display: -webkit-box;
            -webkit-line-clamp: 3;
            -webkit-box-orient: vertical;
            overflow: hidden;
        }

        /* Responsive */
        @media (max-width: 900px) {
            .featured-grid {
                grid-template-columns: 1fr;
                padding: 0;
            }

            .media-container {
                padding: 40px 20px;
            }

            .content-area {
                padding: 0 30px 40px;
            }

            .headline {
                font-size: 32px;
            }
        }

        @media (max-width: 767px) {
            .region-banner { display: none; } /* Simplify for mobile view */
            .global-nav ul { display: none; } /* Hide nav items for simplicity */
            .sub-nav-links span:not(:first-child):not(:last-child) { display: none; } /* Only logo and search */
            .search-box { width: auto; }

            .news-list {
                grid-template-columns: 1fr;
            }
        }
    </style>
</head>
<body>

    <!-- 1. Region Selector Banner -->
    <div class="region-banner">
        <span>Choose another country or region to see content specific to your location and shop online.</span>
        <div style="display:flex; align-items:center;">
            <button class="region-selector">
                <span style="margin-left:auto;">Hong Kong</span>
                <span>▼</span>
            </button>
            <button class="btn-continue">Continue</button>
            <button class="close-banner">×</button>
        </div>
    </div>

    <!-- 2. Global Navigation -->
    <nav class="global-nav">
        <ul>
            <li><svg width="14" height="14" viewBox="0 0 14 14" fill="currentColor"><path d="M12.5 0h-11C0.67 0 0 0.67 0 1.5v11C0 13.33 0.67 14 1.5 14h11c0.83 0 1.5-0.67 1.5-1.5v-11c0-0.83-0.67-1.5-1.5-1.5zM10 10H4V9h6v1zm0-2H4V7h6v1zm0-2H4V5h6v1z"/></svg></li>
            <li>Store</li>
            <li>Mac</li>
            <li>iPad</li>
            <li>iPhone</li>
