    </nav>

    <!-- 3. Sub Navigation (Newsroom Specific) -->
    <header class="sub-nav">
        <div class="container sub-nav-inner">
            <div class="brand-logo">Newsroom</div>
            <div class="sub-nav-links">
                <span>Apple Services</span>
                <span>Apple Stories</span>
                <div class="search-box">
                    <span>🔍</span>
                    <span>Search Newsroom</span>
                </div>
            </div>
        </div>
    </header>

    <!-- 4. Main Content -->
    <main class="container">

        <h1 class="section-title">Latest News</h1>

        <!-- FEATURED HERO SECTION (Grid Layout Analysis Point 1 & 2) -->
        <section class="featured-grid">
            <!-- Left: Visuals (Image Area) -->
            <article class="media-container">
                <!-- Using placeholder images to simulate the phone screens in screenshot -->
                <div class="phone-mockup" style="background: url('https://images.unsplash.com/photo-1611532736570-eb8cdd0a458c?auto=format&fit=crop&w=400&q=80') center/cover;"></div>
                <div class="phone-mockup secondary" style="background: url('https://images.unsplash.com/photo-1579783902614-a3fb3927b6a5?auto=format&fit=crop&w=400&q=80') center/cover;"></div>
            </article>

            <!-- Right: Text Content -->
            <article class="content-area">
                <span class="tag">Update</span>
                <h2 class="headline">Apple Arcade levels up with Block Blast!+ and Art of Fauna: Cozy Puzzles+</h2>
                <p class="description">Two new titles are joining Apple Arcade this month, bringing unique puzzle experiences to players across iPhone, iPad, Mac and Apple TV.</p>
            </article>
        </section>

        <!-- LIST GRID (Grid Layout Analysis Point 3) -->
        <section class="news-list">

            <!-- Card 1 -->
            <article class="news-card">
                <div class="news-img-wrapper">
                    <img src="https://images.unsplash.com/photo-1621768216002-5ac171876625?auto=format&fit=crop&w=600&q=80" alt="MacBook Air" class="news-img">
                </div>
                <div class="news-body">
